var TITLE = {
	city: "Mayor",
	state: "Governor",
	federal: "President"
};
function holderAt(level, year) {
	const list = HOLDERS[level];
	let h = list[0];
	for (const x of list) if (x[0] <= year + .01) h = x;
	return {
		name: h[1],
		party: h[2],
		lean: h[3],
		title: TITLE[level],
		from: Math.floor(h[0])
	};
}
var holderNow = (g, level) => familyHolder(g, level) ?? holderAt(level, cal(g).year + [
	"Spring",
	"Summer",
	"Autumn",
	"Winter"
].indexOf(cal(g).season) / 4);
