			const wl = m.waterLevel[Math.floor((ay + by) / 2) * m.width + Math.floor((ax + bx) / 2)] || Math.min(gA, gB) - 8;
			const lift = Math.max(0, wl + (rail ? 17 : type === "covered" ? 9 : built >= 1920 ? 22 : 14) - Math.min(gA, gB));
			const N = Math.max(8, Math.round(len * 4));
