/** local (along, across) → tile (u, v) */
function tf(f, a, c) {
	return f === 0 ? [a, c] : f === 1 ? [-c, a] : f === 2 ? [-a, -c] : [c, -a];
}
function drawParts(p, f, parts) {
	const boxes = parts.map((q) => {
		const [u0, v0] = tf(f, q.a0, q.c0), [u1, v1] = tf(f, q.a1, q.c1);
		return {
			...q,
			u0: Math.min(u0, u1),
			u1: Math.max(u0, u1),
			v0: Math.min(v0, v1),
			v1: Math.max(v0, v1)
		};
	});
	boxes.sort((a, b) => (a.layer ?? 0) - (b.layer ?? 0) || a.u1 + a.v1 - (b.u1 + b.v1));
	for (const b of boxes) {
		const A = (z) => p.P(b.u0, b.v0, z), B = (z) => p.P(b.u1, b.v0, z), C = (z) => p.P(b.u1, b.v1, z), D = (z) => p.P(b.u0, b.v1, z);
		p.poly([
			D(b.z0),
			C(b.z0),
			C(b.z1),
			D(b.z1)
		], b.col);
		p.poly([
			C(b.z0),
			B(b.z0),
			B(b.z1),
			C(b.z1)
		], sh(b.col, .72));
		p.poly([
			A(b.z1),
			B(b.z1),
			C(b.z1),
			D(b.z1)
		], b.top ?? sh(b.col, 1.18));
	}
}
/** wheels as dark discs at (along, across); the near ones are drawn after the body */
function wheels(p, f, ws, frame, near, spoke = "#8a8478") {
	for (const [a, c, r] of ws) {
		const [u, v] = tf(f, a, c);
		const [cu, cv] = tf(f, a, 0);
		if (u + v > cu + cv + 1e-6 !== near) continue;
		const [x, y] = p.P(u, v, r);
		const d = Math.max(2, Math.round(r * 2));
		p.px(x - d / 2, y - d / 2, "#1a1816", d, d);
		if (d >= 3) p.px(x - d / 2 + (frame ? d - 2 : 1), y - d / 2 + (frame ? 1 : d - 2), spoke);
	}
}
/** a horse at along a0..a0+0.2, legs moving with the frame */
function horse(p, f, a0, c, col, frame, stage) {
	const legsAt = [
		[a0 + .035, c - .022],
		[a0 + .035, c + .022],
		[a0 + .15, c - .022],
		[a0 + .15, c + .022]
	];
	if (stage === "body") {
		drawParts(p, f, [{
			a0: a0 + .02,
			a1: a0 + .17,
			c0: c - .03,
			c1: c + .03,
			z0: 4,
			z1: 7,
			col
		}, {
			a0: a0 + .15,
			a1: a0 + .21,
			c0: c - .018,
			c1: c + .018,
			z0: 6,
			z1: 10,
			col: sh(col, .92),
			layer: 1
		}]);
		return;
	}
	const [cu, cv] = tf(f, a0 + .1, c);
	for (const [k, [a, cc]] of legsAt.entries()) {
		const [u, v] = tf(f, a, cc);
		const near = u + v > cu + cv;
		if (stage === "legs-near" !== near) continue;
		const [ub, vb] = tf(f, a + (frame ? (k < 2 ? -.025 : .025) * (k % 2 ? 1 : -1) : 0), cc);
		p.line(p.P(u, v, 4.5), p.P(ub, vb, .5), sh(col, .75));
	}
}
/** era bucket for motor vehicles */
function motorEra(year) {
	return year < 1915 ? 0 : year < 1932 ? 1 : year < 1950 ? 2 : year < 1966 ? 3 : 4;
}
