				B(-L, L - .16, -.055, .055, 2.8, 8.5, c.col);
				B(L - .16, L - .05, -.068, .068, 2.8, 11, c.col);
				B(L - .15, L - .06, -.069, .069, 8.5, 10, lit ? "#ffd27a" : "#8ca0a8");
