	placing = false;
	$("placing").checked = false;
	proposal = p ?? {
		kind,
		x: game.company.x,
		y: game.company.y,
		size: 1,
		ok: false,
		reason: "No suitable spot found nearby — click the map to try one",
		cost: 0,
		industry: ind,
		displaced: 0
	};
