/** show a road on the map, with what it costs and does; pay, lobby or cancel */
function startRoad(p) {
	proposal = null;
	roadPreview = p;
	const mid = p.path[Math.floor(p.path.length / 2)];
	const span = Math.max(...p.path.map((i) => Math.hypot(i % map.width - mid % map.width, (i / map.width | 0) - (mid / map.width | 0))));
	centerOn(mid % map.width, mid / map.width | 0, span > 60 ? .25 : span > 30 ? .5 : .75);
	placeBar();
	requestRender();
}
/** your businesses on the map: a small flag in the company colours, named when you're close */
/** the flags on the businesses you own (drawn in CSS pixels: the context is already scaled) */
function drawHoldings(c) {
	const h = game.company?.holdings;
	if (!h?.biz.length || c.zoom < .25) return;
	ctx.save();
	ctx.font = "bold 11px ui-monospace, monospace";
	ctx.textBaseline = "bottom";
	const cw = canvas.width / dpr, chh = canvas.height / dpr;
	for (const b of h.biz) {
		const [wx, wy] = project(b.x + .5, b.y + .5, map.elevation[b.y * map.width + b.x]);
		const x = (wx - c.x) * c.zoom, y = (wy - c.y) * c.zoom;
		if (x < -50 || y < -50 || x > cw + 50 || y > chh + 50) continue;
		const pole = 18 * Math.max(.6, Math.min(1.5, c.zoom));
		ctx.strokeStyle = "#1a1a1a";
		ctx.lineWidth = 2;
		ctx.beginPath();
		ctx.moveTo(x, y);
		ctx.lineTo(x, y - pole);
		ctx.stroke();
		ctx.fillStyle = "#e0b050";
		ctx.fillRect(x, y - pole, 10, 7);
		ctx.fillStyle = "#8e3f2e";
		ctx.fillRect(x, y - pole + 7, 10, 2);
		if (c.zoom >= .75) {
			const name = bizDef(b.id).name;
			const w = ctx.measureText(name).width + 8;
			ctx.fillStyle = "rgba(20,20,24,0.85)";
			ctx.fillRect(x + 12, y - pole - 2, w, 15);
			ctx.fillStyle = "#ffd34a";
			ctx.fillText(name, x + 16, y - pole + 12);
		}
	}
	ctx.restore();
}
/** the planned road drawn over the map: dashed, with the new bridge in a warmer colour */
function drawRoadPreview() {
	const p = roadPreview;
	if (!p) return;
	const pt = (i) => tileScreen(i % map.width, i / map.width | 0);
	ctx.save();
	ctx.lineWidth = Math.max(2, 5 * cam.zoom);
	ctx.lineCap = "round";
	ctx.lineJoin = "round";
	ctx.setLineDash([Math.max(4, 10 * cam.zoom), Math.max(3, 6 * cam.zoom)]);
	ctx.lineDashOffset = -performance.now() / 60;
	let water = map.terrain[p.path[0]] === 0;
	ctx.beginPath();
	ctx.moveTo(...pt(p.path[0]));
	for (let k = 1; k < p.path.length; k++) {
		const w = map.terrain[p.path[k]] === 0;
		ctx.lineTo(...pt(p.path[k]));
		if (w !== water || k === p.path.length - 1) {
			ctx.strokeStyle = water ? "#ff8a4a" : "#ffd34a";
			ctx.stroke();
			ctx.beginPath();
			ctx.moveTo(...pt(p.path[k]));
			water = w;
		}
	}
	ctx.restore();
}
function placeBar() {
	const el = $("placeBar");
	if (roadPreview) {
		roadBar(el, roadPreview);
		return;
	}
	if (!proposal) {
		el.hidden = true;
		return;
	}
	const p = proposal;
	el.innerHTML = `<span><b>${PROJECTS[p.kind].name + (p.kind === "found" && p.industry ? `: ${INDUSTRIES[p.industry].name}` : "")}</b> — ${p.ok ? `${money(p.cost)}${p.displaced ? ` · ${fmt(p.displaced)} people moved out` : ""}` : `<span class="why">${esc(p.reason ?? "Can't build here")}</span>`}<br><span class="hint">Click the map to move it.</span></span>
    <button id="placeOk" class="primary" ${p.ok && game.company && game.company.cash >= p.cost ? "" : "disabled"}>Build here</button><button id="placeCancel">Cancel</button>`;
	el.hidden = false;
	$("placeOk").addEventListener("click", () => {
		const r = buildProject(game, p);
		worksStatus(r.text);
		if (r.ok) {
			proposal = null;
			renderer.updateHeights();
			renderer.invalidateAll();
		}
		afterChange();
		placeBar();
	});
	$("placeCancel").addEventListener("click", stopPlacing);
}
function roadBar(el, p) {
	const pay = roadBlocked(game, p, "pay"), lobby = roadBlocked(game, p, "lobby");
	el.innerHTML = `<span><b>${p.bridge ? "Bridge" : "Road"} to ${esc(p.to)}</b> — ${distance(p.path.length * map.metersPerTile)}${p.bridgeTiles ? `, new bridge ${feet(p.bridgeTiles * map.metersPerTile)}` : ""}${p.displaced ? ` · ${fmt(p.displaced)} people moved` : ""}<br><span class="hint">${Math.round(p.before)} → ${Math.round(p.after)} min to the works · about ${fmt(p.gain)} more people in reach</span></span>
    <button id="roadPay" class="primary" ${pay ? `disabled title="${esc(pay)}"` : ""}>Pay ${money$2(p.cost)}</button><button id="roadLobby" ${lobby ? `disabled title="${esc(lobby)}"` : `title="Spend influence; the city builds it in ${lobbySeasons(p)} seasons"`}>Lobby (Inf ${lobbyInfluence(p)})</button><button id="placeCancel">Cancel</button>`;
	el.hidden = false;
	for (const [id, how] of [["roadPay", "pay"], ["roadLobby", "lobby"]]) $(id).addEventListener("click", () => {
		const r = orderRoad(game, p, how);
		worksStatus(r.text);
		if (r.ok) {
			roadPreview = null;
			renderer.invalidateAll();
		}
		afterChange();
		placeBar();
	});
	$("placeCancel").addEventListener("click", stopPlacing);
}
function nextSeason() {
	if (game.over) return;
	if (game.pendingDecision) {
		decisionCard(game, $("decision"), () => afterChange());
		return;
	}
	if (game.family?.succession) {
		successionCard(game, $("succession"), () => afterChange());
		return;
	}
	resetBusinessUi();
	resetWorksUi();
	resetTownUi();
	resetHoldingsUi();
	resetStruggleUi();
	if (proposal || roadPreview) stopPlacing();
	advanceTurn(game);
	afterTurn();
}
function nextYear() {
	if (game.over) return;
	if (game.pendingDecision) {
		decisionCard(game, $("decision"), () => afterChange());
		return;
	}
	if (game.family?.succession) {
		successionCard(game, $("succession"), () => afterChange());
		return;
	}
	if (yearRunning) return;
	resetBusinessUi();
	resetWorksUi();
	resetTownUi();
	resetHoldingsUi();
	resetStruggleUi();
	if (proposal || roadPreview) stopPlacing();
	yearRunning = true;
	const step = () => {
		advanceTurn(game);
		if (!game.over && !game.pendingDecision && !game.family?.succession && cal(game).season !== "Spring") {
			refreshPanels();
			requestRender();
			requestAnimationFrame(step);
			return;
		}
		yearRunning = false;
		afterTurn();
	};
	step();
}
var yearRunning = false;
/** the industries a company can be founded in (the modern ones open as the years go by) */
function industryOptions() {
	const sel = $("industry"), list = industriesIn(game ? cal(game).year : 1850);
	if (sel.options.length === list.length) return;
	sel.innerHTML = list.map((k) => `<option value="${k}"${k === industry ? " selected" : ""}>${INDUSTRIES[k].name}</option>`).join("");
}
function afterTurn() {
	if (!game.company) industryOptions();
	afterChange();
	if (cal(game).season === "Spring" || game.over) autosave();
	if (!$("trends").hidden) trendsView(game, $("trends"), setTab);
	if (selected && !$("query").hidden) {
		const el = $("query");
		el.innerHTML = queryCard({
			game,
			map,
			renderer
		}, selected.x, selected.y);
	}
	showNews();
	if (game.over) {
		stopPlay();
		showFinal();
	}
}
/** ms per season at each speed: 1× takes a game (540 seasons) about two hours */
var SPEED_MS = [
	0,
	13300,
	6650,
	3300,
	900
];
var speed = 0;
var lastSpeed = 1;
function setSpeed(k) {
	if (playTimer) clearInterval(playTimer);
	playTimer = 0;
	speed = game?.over ? 0 : k;
	if (speed > 0) {
		lastSpeed = speed;
		let due = performance.now() + SPEED_MS[speed];
		playTimer = window.setInterval(() => {
			const now = performance.now();
			const why = holdReason();
			showHold(why);
			if (why) {
				due = now + SPEED_MS[speed];
				return;
			}
			if (now < due || renderer.pending > 40) return;
			if (speed === 4 && game.news[game.news.length - 1]?.turn === game.turn && now - newsAt < 2500) return;
			due = now + SPEED_MS[speed];
			nextSeason();
		}, 100);
	}
	speedUI();
	holdShown = "-";
	showHold("");
}
function toggleStruggle(force) {
	const el = $("struggle");
	const open = force ?? el.hidden;
	el.hidden = !open;
	$("struggleBtn").classList.toggle("on", !!open);
	if (open) {
		if (!$("trends").hidden) toggleTrends(false);
		struggleView(game, el, () => afterChange(), () => toggleStruggle(false));
	}
}
function toggleTrends(force) {
	const el = $("trends");
	if (!(force ?? el.hidden)) {
		el.hidden = true;
		$("trendsBtn").classList.remove("on");
		return;
	}
	trendsView(game, el, setTab);
	$("trendsBtn").classList.add("on");
}
/** why the clock is waiting for you, if it is */
function holdReason() {
	if (!$("menu").hidden) return "Main menu open";
	if (yearRunning) return "Playing out the year";
	if (game.pendingDecision) {
		if ($("decision").hidden) decisionCard(game, $("decision"), () => afterChange());
		return "Waiting for your decision";
	}
	if (game.family?.succession) {
		if ($("succession").hidden) successionCard(game, $("succession"), () => afterChange());
		return "Waiting for the succession";
	}
	if (proposal) return "Waiting while you place the building";
	if (roadPreview) return "Waiting while you look at the road";
	return "";
}
var holdShown = "";
function showHold(why) {
	if (why === holdShown) return;
	holdShown = why;
	const b = $("playBtn");
	b.classList.toggle("held", speed > 0 && !!why);
	b.title = speed > 0 && why ? `${why} — play resumes after` : "Play / pause (P)";
}
var SPEED_WORD = [
	"",
	"1×",
	"2×",
	"4×",
	"8×"
];
/** the play button and the speed it plays at */
function speedUI() {
	const play = $("playBtn");
	play.textContent = speed > 0 ? "❚❚" : "▶";
	play.classList.toggle("on", speed > 0);
	$("speedBtn").textContent = SPEED_WORD[speed || lastSpeed];
}
function startPlay() {
	if (!game.over) setSpeed(lastSpeed);
}
function stopPlay() {
	setSpeed(0);
}
function updateTimeControls() {
	const over = !!game.over;
	for (const id of [
		"next",
		"playBtn",
		"speedBtn"
	]) $(id).disabled = over;
	$("next").textContent = over ? "The end" : "Next season ▶";
}
/** jump to the best affordable site for the chosen industry (press again for the next one) */
function showBestSite() {
	const pSat = popSAT(map, game.world);
	const fp = footprintTiles(map, industry);
	const cands = [];
	for (let y = 4; y < map.height - fp - 4; y += 5) for (let x = 4; x < map.width - fp - 4; x += 5) {
		const r = evaluateSite(map, game.world, game.fields, industry, x, y, pSat);
		if (r.ok && r.cost <= foundingCapital(industry, cal(game).year)) cands.push({
			x,
			y,
			score: r.score
		});
	}
	cands.sort((a, b) => b.score - a.score);
	const pick = cands.find((c) => siteTried.every((t) => Math.hypot(t.x - c.x, t.y - c.y) > 30));
	if (!pick) {
		siteTried = [];
		return;
	}
	siteTried.push(pick);
	selected = {
		x: pick.x,
		y: pick.y
	};
	centerOn(pick.x + fp / 2, pick.y + fp / 2, 1);
	siteReport();
	requestRender();
}
function showFinal() {
	const g = game, st = g.stats, c = g.company;
	const pop = totalPopulation(g);
	const rows = [["Valley population, peak", `${fmt(st.peakPop)} (${st.peakPopYear})`], [`Valley population, ${cal(g).year}`, fmt(pop)]];
	let verdict;
	if (c) {
		rows.unshift([esc(c.name), `founded ${st.foundedYear ?? "?"} · ${esc(businessNow(c))}`], ["Processes owned", `${allWorks(c).reduce((n, w) => n + w.techs.length, 0)} (${esc(INDUSTRIES[c.industry].tech.filter((t) => c.techs.includes(t.id)).map((t) => t.name).join(", "))})`], ["Seasons in operation", fmt(c.seasonsOperating)], ["Lifetime output", fmt(c.produced)], ["Most workers", `${fmt(st.peakEmployees)} (${st.peakEmployeesYear})`], ["Cash, peak", `${money(st.peakCash)} (${st.peakCashYear})`], [`Cash, ${cal(g).year}`, money(c.cash)], ["Strikes", fmt(st.strikes)], ["Reputation · labour · influence", `${Math.round(c.biz.meters.reputation)} · ${Math.round(c.biz.meters.labour)} · ${Math.round(c.biz.meters.influence)}`]);
		if (c.others.length) rows.splice(1, 0, ["Works owned", allWorks(c).map((w) => w.name).join(", ")]);
		verdict = c.bankrupt ? `${c.name} went into receivership in ${cal(g).year}. The bank sold the works to whoever would have them.` : c.cash > 0 ? `${c.name} is still standing when the valley's great mills go quiet. Whether the town around it survives is another question.` : `${c.name} did not outlast the collapse. The works stand cold beside the river.`;
	} else verdict = "You never founded a company. The valley's story went on without you.";
	const epi = c ? epilogue() : [];
	const lg = legacy(g), f = g.family;
	const legacyHtml = c ? `<div class="legacy"><div><small>Fortune</small><b>${lg.fortune}</b></div><div><small>The Valley</small><b>${lg.valley}</b></div><div><small>History's verdict</small><b>${lg.verdict}</b></div><div><small>Legacy</small><b>${lg.total}</b></div></div>
    <p><b>${esc(lg.title)}.</b> ${lg.lines.map(esc).join(" ")}</p>
    ${f ? `<ol class="tree">${f.heads.map((h) => `<li><b>${esc(fullName(g, h))}</b> (${h.from}–${h.to ?? cal(g).year}) · ${esc(PATHS[h.path].name.toLowerCase())}${h.offices?.length ? ` · ${esc(h.offices.join(", "))}` : ""}${h.verdict ? ` — ${esc(h.verdict)}` : ""}</li>`).join("")}</ol>` : ""}
    <p style="font-size:12px">${topMarks(g, 4).map((m) => `${m.year}: ${esc(whoDid(g, m))} ${esc(m.text)}`).join(" · ")}</p>
    <table class="dyn">${[...DYNASTIES.map(([n, a, b, cc, note]) => ({
		n,
		t: Math.round((a + b + cc) / 3),
		note,
		you: false
	})), {
		n: `The ${f?.surname ?? ""} family`,
		t: lg.total,
		note: lg.title.toLowerCase(),
		you: true
	}].sort((a, b) => b.t - a.t).map((d) => `<tr class="${d.you ? "you" : ""}"><td>${esc(d.n)}</td><td>${d.t}</td><td>${esc(d.note)}</td></tr>`).join("")}</table>` : "";
	$("final").innerHTML = `<div class="paper">
    <div class="mast"><span>Pittsburgh Post-Gazette</span><span>${c?.bankrupt ? `${cal(g).season} ${cal(g).year}` : "Winter 1985"}</span></div>
    <h3>${c?.bankrupt ? "Receivers Sell the Works" : "The Mills Go Quiet"}</h3>
    <p>${verdict}</p>
    ${epi.length ? `<p class="epilogue">${epi.join(" ")}</p>` : ""}
    ${legacyHtml}
    <table>${rows.map(([k, v]) => `<tr><td>${k}</td><td>${v}</td></tr>`).join("")}</table>
    ${c && c.biz.record.length ? `<p style="font-size:12px"><b>Your choices:</b> ${c.biz.record.filter((r) => r.includes("—")).concat(c.biz.record.filter((r) => !r.includes("—")).slice(-4)).slice(0, 8).map(esc).join(" · ")}</p>` : ""}
    <div class="actions"><button id="finalLook">Look around</button><button id="finalNew" class="primary">New town</button></div>
  </div>`;
	$("final").hidden = false;
	$("finalLook").addEventListener("click", () => {
		$("final").hidden = true;
	});
	$("finalNew").addEventListener("click", () => {
		newTown(Math.floor(Math.random() * 1e6));
		showNews();
	});
}
/** a few sentences on how the company played its part, from the choices it made and how it ended */
function epilogue() {
	const g = game, c = g.company, f = {
		...g.flags,
		...c.biz.flags
	}, m = c.biz.meters, out = [];
	const st = techStanding(g, c);
	if (f.sheltered) out.push("In 1850 its cellars hid fugitives on the road to Canada.");
	if (f.stayedUnion1897) out.push("When J&L broke with the union in 1897, it kept faith with the Amalgamated.");
	else if (f.nonUnion1897) out.push("It followed J&L out of the union in 1897.");
	if (f.usSteel === "pact") out.push("It dined with Judge Gary and held the trust's prices.");
	else if (f.usSteel === "sold") out.push("It sold a works to Morgan's trust in 1901.");
	if (f.bannedMeetings) out.push("It shut Mother Jones out of its company town in 1919.");
	if (f.warOrders || f.warContract) out.push("It took the government's war orders.");
	if (f.conference) out.push("It joined the Allegheny Conference to clear the smoke.");
	if (f.decreeStalled) out.push("It signed the clean-air decree and dragged its feet.");
	if (f.relief || f.reliefGiven) out.push("In hard times it fed the families out of work.");
	if (f.laidOff) out.push("When the orders stopped, it laid men off.");
	if (c.library) out.push("A library with its name on it still stands.");
	if (f.endowed) out.push("The university keeps a laboratory in its name.");
	if (st.behind.length >= 2) out.push(`It never caught up with the industry: at the end it still lacked ${st.behind.length} processes its rivals ran.`);
	else if (c.techs.length > 3) out.push("It kept its furnaces up to date to the end.");
	out.push(m.reputation >= 30 ? "The valley remembers it kindly." : m.reputation <= -40 ? "The valley remembers it bitterly." : "The valley remembers it as one mill among many.");
	if (m.labour <= -30) out.push("Its men never trusted it.");
	else if (m.labour >= 30) out.push("Its men stood by it.");
	return out;
}
function afterChange() {
	drawMinimapBase();
	refreshPanels();
	updateTimeControls();
	requestRender();
}
if (new URLSearchParams(location.search).has("dev") || false) Object.assign(window, { mt: {
	get game() {
		return game;
	},
	get map() {
		return map;
	},
	get renderer() {
		return renderer;
	},
	cam,
	center: (x, y, z) => centerOn(x, y, z),
	select: (x, y) => {
		selected = {
			x,
			y
		};
		siteReport();
		requestRender();
	},
	overlay: (id) => setOverlay(id),
	chain: () => currentChain(),
	industry: (id) => {
		industry = id;
		$("industry").value = id;
		industryNote();
		siteReport();
		requestRender();
	},
	next: (n = 1) => {
		for (let k = 0; k < n; k++) advanceTurn(game);
		afterTurn();
	},
	found: (x, y, id = industry) => {
		const r = foundCompany(game, id, x, y);
		renderer.updateHeights();
		afterChange();
		return r;
	},
	library: () => {
		const r = fundLibrary(game);
		afterChange();
		return r;
	},
	steps: () => {
		const r = buildSteps(game);
		afterChange();
		return r;
	},
	incline: () => {
		const r = buildIncline(game);
		afterChange();
		return r;
	},
	tech: (ids) => {
		if (game.company) {
			game.company.techs = ids;
			game.world.version++;
			afterChange();
		}
	},
	tod: (v) => {
		$("tod").value = v;
		requestRender();
	},
	get pending() {
		return renderer.pending;
	},
	query: (x, y) => {
		selected = {
			x,
			y
		};
		const [sx, sy] = tileScreen(x, y);
		showQuery(x, y, sx, sy);
		requestRender();
	},
	get traffic() {
		return traffic;
	},
	/** place a test landmark of a kind at a named place (for checking sprites) */
	landmark: (kind, place) => {
		const r = placeLandmark(game, {
			id: `test-${kind}-${place}`,
			name: kind,
			kind,
			place
		});
		renderer.invalidateAll();
		afterChange();
		return r;
	},
	/** fire an event's effects by name (for testing) */
	fire: (name) => {
		const fx = allEffects()[name];
		if (fx) applyEffects(game, name, fx);
		const d = allDecisions()[name]?.(game);
		if (d) game.pendingDecision = d;
		afterChange();
		return {
			effects: fx?.length ?? 0,
			decision: !!d
		};
	},
	sound
} });
start().catch((e) => {
	document.body.innerHTML = `<pre style="color:#e06a5a;padding:20px">${String(e?.stack ?? e)}</pre>`;
});
